## Code Example
```c
// Fixed-size allocator implementation sketch
typedef struct Block { 
    size_t size; 
    struct Block* next; 
    int free; 
} Block;

static unsigned char pool[64*1024];
static Block* free_list = NULL;

void init_buffer() {
    Block* initial = (Block*)pool;
    initial->size = sizeof(pool) - sizeof(Block);
    initial->free = 1;
    initial->next = NULL;
    free_list = initial;
}
```

